// Real Tab/Shift+Tab/Enter/Escape events; no mouse operations. Generated files only.
import fs from 'node:fs/promises';import os from 'node:os';import path from 'node:path';import {PDFDocument,PDFName,PDFString} from 'pdf-lib';import {expect} from '@playwright/test';
import {launchReader} from '../tests/helpers/reader-launch.mjs';import {readerRuntime} from '../tests/helpers/reader-runtime.mjs';import {closeReaderApp} from '../tests/helpers/reader-desktop.mjs';
const root=await fs.mkdtemp(path.join(os.tmpdir(),'pdfix-keyboard-walk-')),report={root,screens:[],errors:[],screenshots:[]};let app,page,timer;
const source=path.join(root,'source.pdf'),other=path.join(root,'other.pdf');
for(const [file,revision]of [[source,false],[other,true]]){const doc=await PDFDocument.create();for(let i=1;i<=3;i++)doc.addPage([400,600]).drawText('Keyboard drawing page '+i+(revision?' revised':''),{x:40,y:500,size:14});const c=doc.context,ref=c.register(c.obj({Type:'Outlines',Count:1})),entry=c.register(c.obj({Title:PDFString.of('Last keyboard page'),Parent:ref,Dest:[doc.getPage(2).ref,'Fit']}));c.lookup(ref).set(PDFName.of('First'),entry);c.lookup(ref).set(PDFName.of('Last'),entry);doc.catalog.set(PDFName.of('Outlines'),ref);await fs.writeFile(file,await doc.save());}
async function activate(locator,key='Enter'){await locator.focus();await locator.press(key);}
async function tools(group='View'){const mode=page.getByRole('group',{name:'Document mode',exact:true}).getByRole('button',{name:/^Mode: /});if(await mode.isVisible()&&await mode.getAttribute('aria-label')!=='Mode: Build'){await activate(mode);await page.keyboard.press('End');await page.keyboard.press('Enter');}const tabs=page.getByRole('tablist',{name:'PDF tool groups',exact:true});if(await tabs.isVisible()){await activate(tabs.getByRole('tab',{name:group,exact:true}));if(group==='View'){const more=page.getByRole('button',{name:'More',exact:true});if(await more.isVisible()&&!await more.evaluate(n=>n.parentElement.open))await activate(more);}return;}const menu=page.locator('.document-area .reader-view-options').first();if(!await menu.evaluate(n=>n.open))await activate(menu.locator('summary').first());for(const s of await menu.locator('.pdf-tool-group > summary').all())if(!await s.evaluate(n=>n.parentElement.open))await activate(s);}
async function ready(){await expect(page.locator('.document-area .pdf-paper').first()).toHaveAttribute('data-ready','true',{timeout:60000});}
async function walk(scope,name){
 const expected=await scope.evaluate(root=>{
  globalThis.keyboardWalkIds??=new WeakMap();globalThis.keyboardWalkNext??=0;
  const label=n=>n.getAttribute('aria-label')||[...(n.labels||[])].map(l=>l.textContent).join(' ')||n.textContent.trim()||n.title;
  const candidates=[...root.querySelectorAll('button,input,textarea,select,a[href],summary,[tabindex]')].filter(n=>{if(n.matches(':disabled')||n.tabIndex<0||n.closest('[hidden],[inert]')||!n.getClientRects().length||n.checkVisibility?.()===false||getComputedStyle(n).visibility==='hidden')return false;for(let p=n.parentElement;p&&p!==root.parentElement;p=p.parentElement)if(p.tagName==='DETAILS'&&!p.open&&!p.firstElementChild.contains(n))return false;return true;});
  return candidates.map(n=>{if(!globalThis.keyboardWalkIds.has(n))globalThis.keyboardWalkIds.set(n,++globalThis.keyboardWalkNext);return {id:globalThis.keyboardWalkIds.get(n),name:label(n).replace(/\s+/g,' ').slice(0,100),iconUnnamed:n.tagName==='BUTTON'&&/^[↑↓×‹›−+]$/.test(n.textContent.trim())&&!n.getAttribute('aria-label')&&!n.title};});
 });
 const wanted=new Map(expected.map(v=>[v.id,v])),seen=new Map(),invisible=[];let repetitions=0,last;
 for(let i=0;i<Math.max(150,expected.length*5+80)&&seen.size<wanted.size;i++){
  await page.keyboard.press('Tab');const v=await page.evaluate(()=>{const n=document.activeElement,s=getComputedStyle(n);return {id:globalThis.keyboardWalkIds?.get(n),tag:n.tagName,name:n.getAttribute('aria-label')||n.textContent?.trim().slice(0,80),focusVisible:n.matches(':focus-visible'),ring:(parseFloat(s.outlineWidth)>0&&s.outlineStyle!=='none')||s.boxShadow!=='none'};});
  if(wanted.has(v.id)){if(!seen.has(v.id)){seen.set(v.id,{...v,...wanted.get(v.id)});if(!v.focusVisible||!v.ring)invisible.push(v);}if(v.id===last)repetitions++;else repetitions=0;if(repetitions>5)break;last=v.id;}
 }
 const missing=expected.filter(v=>!seen.has(v.id)),unnamed=expected.filter(v=>!v.name||v.iconUnnamed),item={name,expected:expected.length,reached:seen.size,missing,invisible,unnamed,order:[...seen.values()].map(v=>v.name)};
 item.pass=!missing.length&&!invisible.length&&!unnamed.length;report.screens.push(item);console.log((item.pass?'PASS ':'FAIL ')+name+' '+seen.size+'/'+expected.length);return item;
}
async function visibleFocus(message){await expect.poll(()=>page.evaluate(()=>{const n=document.activeElement;return n.tagName!=='BODY'&&n.isConnected&&!!n.getClientRects().length&&!n.closest('[hidden],[inert]')&&n.checkVisibility();}),{timeout:3000,message}).toBe(true);}
async function closeDialog(dialog){await page.keyboard.press('Escape');if(await page.getByRole('button',{name:'Discard unsaved set and close',exact:true}).isVisible())await activate(page.getByRole('button',{name:'Discard unsaved set and close',exact:true}));await expect(dialog).not.toBeVisible({timeout:30000});await expect.poll(()=>page.evaluate(()=>{const n=document.activeElement;return n.tagName!=='BODY'&&n.isConnected&&!!n.getClientRects().length&&!n.closest('[hidden],[inert]');}),{timeout:3000,message:'Dialog should return focus to a visible control after its close event'}).toBe(true);}
async function shot(name){const file=path.join(root,name+'.png');await page.screenshot({path:file});report.screenshots.push(file);}
try{
 app=await launchReader({args:[await readerRuntime()],env:{...process.env,PDFIX_TEST_DATA:path.join(root,'profile'),PDFIX_TEST_VISIBLE:'0'}});page=await app.firstWindow();page.on('pageerror',e=>report.errors.push(e.message));timer=setTimeout(()=>app.process().kill(),600000);
 await app.evaluate(({dialog},file)=>{dialog.showOpenDialog=async()=>({canceled:false,filePaths:[file]});},source);await activate(page.getByRole('button',{name:'Open a file',exact:true}));await ready();await page.keyboard.press('Tab');
 for(const [width,height,text]of [[1366,820,1],[800,620,1.5]]){
  await app.evaluate(({BrowserWindow},[w,h])=>BrowserWindow.getAllWindows()[0].setSize(w,h),[width,height]);
  if(text!==1){await activate(page.getByRole('button',{name:/Settings/}));await page.getByRole('combobox',{name:'Interface text size',exact:true}).focus();await page.getByRole('combobox',{name:'Interface text size',exact:true}).press('End');await activate(page.getByRole('button',{name:'Home',exact:true}));await app.evaluate(({dialog},file)=>{dialog.showOpenDialog=async()=>({canceled:false,filePaths:[file]});},source);await activate(page.getByRole('button',{name:'Open a file',exact:true}));await ready();}
  const tag=width+'-'+text,reader=page.locator('.document-area').first();await walk(reader,'reader '+tag);for(const group of ['Home','View','Comment','Edit','Fill & Sign','Pages','Protect','Measure','Export']){await tools(group);if(group==='Comment')await expect(page.getByRole('toolbar',{name:'Comment tools',exact:true}).getByRole('button',{name:'Select',exact:true})).toBeEnabled();if(group==='Pages')await expect(page.getByRole('region',{name:'Organize PDF pages',exact:true}).getByRole('button',{name:'Rotate output page 1',exact:true})).toBeEnabled();await walk(reader,'tool group '+group+' '+tag);}await tools('View');if(process.env.PDFIX_KEYBOARD_SCREENSHOTS==='1')await shot('reader-focus-'+tag);await page.keyboard.press('Escape');await page.keyboard.press('Escape');
  const nav=reader.getByRole('complementary',{name:'PDF navigation',exact:true});if(!await nav.isVisible()){await tools();await activate(reader.getByRole('button',{name:'Pages panel',exact:true}));await page.keyboard.press('Escape');}const navtab=nav.getByRole('tab',{name:'Pages',exact:true});await navtab.focus();await page.keyboard.press('Home');for(const section of ['Pages','Outline','Saved']){await expect(nav.getByRole('tab',{name:section,exact:true})).toHaveAttribute('aria-selected','true');await walk(nav,'navigation '+section+' '+tag);await nav.getByRole('tab',{name:section,exact:true}).focus();await page.keyboard.press('ArrowRight');}
  for(const mode of ['continuous','facing','text','page']){await tools();const choice=reader.getByRole('combobox',{name:'Reading view',exact:true});await choice.focus();await page.keyboard.press(mode==='page'?'Home':'ArrowDown');await expect(reader.locator('.reading-view')).toHaveValue(mode);if(['continuous','facing'].includes(mode))await expect(reader.locator('.pdf-multi-slot[data-page="1"]')).toHaveAttribute('data-ready','true',{timeout:30000});else if(mode==='page')await ready();else await expect(reader.locator('.readable-page')).toContainText('Keyboard drawing',{timeout:30000});await walk(reader,'view '+mode+' '+tag);}
  for(const [title,group]of [['Print','View'],['Compress a PDF','Export'],['Organize pages','Pages'],['Mark up a PDF','Comment'],['Page numbers and stamps','Pages'],['Edit the PDF outline','Pages'],['Edit PDF page boxes','Pages'],['Print-production marks','Export'],['Inspect and repair thin lines','Export'],['Drawing sheet sets','Measure'],['Compare drawing revisions','Measure']]){
   await tools(group);if(title==='Compare drawing revisions')await app.evaluate(({dialog},file)=>{dialog.showOpenDialog=async()=>({canceled:false,filePaths:[file]});},other);
   const inline=['Organize pages','Mark up a PDF'].includes(title);if(!inline)await activate(reader.getByRole('button',{name:title,exact:true}));const d=inline?page.getByRole('region',{name:title==='Organize pages'?'Organize PDF pages':'PDF comment options',exact:true}):page.getByRole('dialog').last();await expect(d).toBeVisible();
   if(title==='Print')await expect(d.getByRole('button',{name:'Print',exact:true})).toBeEnabled({timeout:120000});if(title==='Compress a PDF')await expect(d.getByRole('button',{name:'Compare quality with original',exact:true})).toBeEnabled({timeout:120000});if(title==='Page numbers and stamps')await expect(d).toHaveAttribute('data-preview-ready','true',{timeout:120000});if(title==='Drawing sheet sets')await expect(d.getByRole('textbox',{name:'Drawing title',exact:true}).first()).toBeEnabled({timeout:120000});
   if(title==='Edit the PDF outline')await expect(d.getByRole('button',{name:'Add top-level section',exact:true})).toBeEnabled({timeout:120000});
   if(title==='Edit PDF page boxes')await expect(d.getByRole('button',{name:'Queue box on selected pages',exact:true})).toBeEnabled({timeout:120000});
   if(title==='Organize pages')await expect(d.getByRole('button',{name:'Rotate output page 1',exact:true})).toBeEnabled({timeout:120000});
   if(title==='Mark up a PDF')await expect(page.getByRole('toolbar',{name:'Comment tools',exact:true}).getByRole('button',{name:'Select',exact:true})).toBeEnabled();
   if(title==='Compare drawing revisions')await expect(d).toHaveAttribute('data-ready','true',{timeout:120000});
   if(title==='Inspect and repair thin lines')await expect(d.getByRole('button',{name:'Inspect strokes',exact:true})).toBeEnabled({timeout:120000});
   await walk(d,title+' '+tag);if(process.env.PDFIX_KEYBOARD_SCREENSHOTS==='1'&&['Edit the PDF outline','Organize pages','Print'].includes(title))await shot(title.replaceAll(' ','-')+'-'+tag);if(inline){await activate(d.getByRole('button',{name:title==='Organize pages'?'Close page workspace':'Close markup workspace',exact:true}));await expect(d).not.toBeVisible();await visibleFocus('Closing '+title);}else await closeDialog(d);
  }
  await tools('Measure');await activate(reader.getByRole('button',{name:'Drawing takeoffs',exact:true}));await expect(page.getByRole('application',{name:'Drawing measurement point placement. Arrow keys move; Space places a point.',exact:true})).toBeVisible();await walk(reader,'drawing measurement '+tag);const overlay=page.getByRole('application',{name:'Drawing measurement point placement. Arrow keys move; Space places a point.',exact:true});await overlay.focus();await overlay.press('Space');await overlay.press('ArrowRight');await overlay.press('Space');await overlay.press('Escape');await expect(overlay).not.toBeVisible();await visibleFocus('Measurement Escape');
  await tools('Comment');await activate(reader.getByRole('button',{name:'Review drawing comments',exact:true}));const comments=page.getByRole('region',{name:'Drawing-wide source comments',exact:true});await expect(comments.getByRole('button',{name:'Inspect source comments',exact:true})).toBeEnabled({timeout:120000});await walk(comments,'comment panel '+tag);await comments.getByRole('button',{name:'Collapse',exact:true}).focus();await page.keyboard.press('Escape');await expect(comments).not.toBeVisible();await visibleFocus('Comments Escape');
 }
}catch(e){report.error=e.stack;if(page)await shot('failure').catch(()=>{});}
finally{clearTimeout(timer);try{await closeReaderApp(app);report.closed=true;}catch(e){report.closeError=e.message;}}
report.pass=report.screens.length===60&&report.screens.every(v=>v.pass)&&!report.errors.length&&!report.error&&report.closed;await fs.writeFile(path.join(root,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({pass:report.pass,closed:report.closed,screens:report.screens.length,failures:report.screens.filter(s=>!s.pass),error:report.error,report:path.join(root,'report.json')},null,2));process.exitCode=report.pass?0:1;
